ITEMS = [
 {"n": 23, "q": {"tr": "كَمْ kaç kısımdır? Kısımları hakkında bilgi veriniz.", "en": "How many kinds has كَمْ, and what are they?"},
  "a": {"tr": "İki: istifhâmiyye — temyizi müfred mansûb (كَمْ دِرْهَمًا؟); haberiyye — temyizi müfred ya da cem' mecrûr (كَمْ رَجُلٍ عِنْدِي، كَمْ رِجَالٍ عِنْدِي). Her ikisinin temyizine مِنْ girebilir; her ikisi de sadr-ı kelâm ister.",
        "en": "Two: interrogative — its tamyīz singular in naṣb (كَمْ دِرْهَمًا؟); predicative — its tamyīz singular or plural in jarr (كَمْ رَجُلٍ عِنْدِي، كَمْ رِجَالٍ عِنْدِي). مِنْ may enter on either's tamyīz, and both claim the head of the sentence."},
  "ar": ["كَمْ دِرْهَمًا", "كَمْ رَجُلٍ عِنْدِي"], "notes": ["al-kinayat-wal-zuruf-al-mabniyya", "tamyiz"], "story": "al-kafiya", "chapter": 7},
 {"n": 24, "q": {"tr": "Mebnî olan zarflar nelerdir?", "en": "Which adverbs are built?"},
  "a": {"tr": "Muzâfun ileyh niyette iken izafetten kesilen zarflar (قَبْلُ، بَعْدُ، وَرَاءُ، فَوْقُ، تَحْتُ، خَلْفُ، قُدَّامُ); zaman ve mekân için حَيْثُ; istikbal için إِذَا; mâzî için إِذْ; mekân için أَيْنَ، أَنَّى; istifhamda zaman için مَتَى، أَيَّانَ; hâl sormak için كَيْفَ; müddetin başı mânâsına مُذْ، مُنْذُ; لَدَى، لَدُنْ; menfî mâzî için قَطُّ; menfî istikbal için عَوْضُ.",
        "en": "The adverbs cut from annexation with the annexed-to in mind (قَبْلُ، بَعْدُ، وَرَاءُ، فَوْقُ، تَحْتُ، خَلْفُ، قُدَّامُ); حَيْثُ of time or place; إِذَا for the future; إِذْ for the past; أَيْنَ، أَنَّى for place; مَتَى، أَيَّانَ asking the time; كَيْفَ asking the state; مُذْ، مُنْذُ for the start of a span; لَدَى، لَدُنْ; قَطُّ for the negated past; عَوْضُ for the negated future."},
  "ar": ["قَبْلُ وَبَعْدُ", "حَيْثُ", "إِذْ", "مُذْ وَمُنْذُ"], "notes": ["al-kinayat-wal-zuruf-al-mabniyya", "al-ghayat-wa-baqiyyat-al-zuruf-al-mabniyya"], "story": "al-kafiya", "chapter": 8},
 {"n": 25, "q": {"tr": "İzafet hâlinde mebnî olması câiz olan zarflar nelerdir?", "en": "Which adverbs may be built while annexed?"},
  "a": {"tr": "Cümleye ve إِذْ'e muzâf zarfların fetha üzere mebnî olması câizdir (يَوْمَ يَنْفَعُ الصَّادِقِينَ صِدْقُهُمْ); مَا ve أَنْ ile birlikte gelen مِثْل، غَيْر، شِبْه'in de fetha üzere mebnî olması câizdir (مِثْلُ قِيَامِي مِثْلَ مَا قَامَ زَيْدٌ).",
        "en": "Those annexed to a sentence or to إِذْ may be built on the fatḥa (يَوْمَ يَنْفَعُ الصَّادِقِينَ صِدْقُهُمْ); so may مِثْل، غَيْر، شِبْه when joined to مَا or أَنْ (مِثْلُ قِيَامِي مِثْلَ مَا قَامَ زَيْدٌ)."},
  "ar": ["يَوْمَ يَنْفَعُ الصَّادِقِينَ صِدْقُهُمْ", "مِثْلُ قِيَامِي مِثْلَ مَا قَامَ زَيْدٌ"], "notes": ["jaiz-al-bina-al-zuruf-al-mudafa-ila-al-jumla-wa-la-al-mukarrara-wa-sifat-ismiha"], "story": "al-kafiya", "chapter": 8},
 {"n": 26, "q": {"tr": "Ma'rifenin tarifi nedir? Kaç nev'dir? Nekrenin tarifi nedir?", "en": "How is the definite defined, how many kinds has it, and how is the indefinite defined?"},
  "a": {"tr": "Ma'rife: belirli bir şey için konulandır. Altı nev': zamirler, alemler, mübhemler (işaret ve mevsûl), lâm ile ma'rife, nidâ ile ma'rife, bunlardan birine izafet-i maneviyye ile muzâf olan. Nekre: belirli olmayan bir şey için konulan lafızdır.",
        "en": "The definite: what is coined for a thing in itself. Six kinds: the pronouns, the proper names, the vague (demonstrative and relative), the article-definite, the vocative-definite, and what is annexed by meaning annexation to one of these. The indefinite: what is coined for a thing not in itself."},
  "ar": ["مَا وُضِعَ لِشَيْءٍ بِعَيْنِهِ", "مَا وُضِعَ لِشَيْءٍ لَا بِعَيْنِهِ"], "notes": ["al-marifa-wal-nakira-fil-kafiya", "al-marifa-al-mudmarat-wal-alam"], "story": "al-kafiya", "chapter": 9},
 {"n": 27, "q": {"tr": "Alemin tarifi nedir? Ma'rifelerin en ma'rifesi nedir?", "en": "How is the proper name defined, and what is the most definite of definites?"},
  "a": {"tr": "Tek bir vaz'la, başkasını kapsamaksızın belirli bir şey için konulan lafızdır. Ma'rifelerin en ma'rifesi mütekellim ve muhâtab zamirleridir.", "en": "What is coined by one coining for a thing in itself without reaching another. The most definite of definites are the pronouns of the speaker and the addressee."},
  "ar": ["مَا وُضِعَ لِشَيْءٍ بِعَيْنِهِ غَيْرَ مُتَنَاوِلٍ غَيْرَهُ بِوَضْعٍ وَاحِدٍ"], "notes": ["al-marifa-al-mudmarat-wal-alam"], "story": "al-kafiya", "chapter": 9},
 {"n": 28, "q": {"tr": "Sayı isimlerinin tarifi nedir? Asılları kaçtır, nelerdir?", "en": "How are the number nouns defined, and what are their roots?"},
  "a": {"tr": "Şeylerin fertlerinin miktarı için konulan lafızdır. Asılları on ikidir: وَاحِدٌ، اثْنَانِ، ثَلَاثَةٌ، أَرْبَعَةٌ، خَمْسَةٌ، سِتَّةٌ، سَبْعَةٌ، ثَمَانِيَةٌ، تِسْعَةٌ، عَشَرَةٌ، مِائَةٌ، أَلْفٌ.", "en": "What is coined for the quantity of the units of things. Twelve roots: وَاحِدٌ، اثْنَانِ، ثَلَاثَةٌ، أَرْبَعَةٌ، خَمْسَةٌ، سِتَّةٌ، سَبْعَةٌ، ثَمَانِيَةٌ، تِسْعَةٌ، عَشَرَةٌ، مِائَةٌ، أَلْفٌ."},
  "ar": ["مَا وُضِعَ لِكَمِّيَّةِ آحَادِ الْأَشْيَاءِ"], "notes": ["asma-al-adad-fil-kafiya"], "story": "al-kafiya", "chapter": 10},
 {"n": 29, "q": {"tr": "Müzekker ve müenneste sayı isimleri nasıl olur?", "en": "How do the number nouns run with masculine and feminine counted nouns?"},
  "a": {"tr": "Müzekkerde: وَاحِدٌ، اثْنَانِ، ثَلَاثَةٌ … عَشَرَةٌ، أَحَدَ عَشَرَ، اثْنَا عَشَرَ، ثَلَاثَةَ عَشَرَ … عِشْرُونَ، أَحَدٌ وَعِشْرُونَ … مِائَةٌ، مِائَةٌ وَوَاحِدٌ … أَلْفٌ، أَلْفَانِ، ثَلَاثَةُ آلَافٍ. Müenneste: وَاحِدَةٌ، اثْنَتَانِ، ثَلَاثٌ، أَرْبَعٌ … عَشْرٌ، إِحْدَى عَشْرَةَ، اثْنَتَا عَشْرَةَ، ثَلَاثَ عَشْرَةَ … عِشْرُونَ، إِحْدَى وَعِشْرُونَ … تِسْعٌ وَتِسْعُونَ، مِائَةٌ، مِائَةٌ وَوَاحِدَةٌ …",
        "en": "Masculine: وَاحِدٌ، اثْنَانِ، ثَلَاثَةٌ … عَشَرَةٌ، أَحَدَ عَشَرَ، اثْنَا عَشَرَ، ثَلَاثَةَ عَشَرَ … عِشْرُونَ، أَحَدٌ وَعِشْرُونَ … مِائَةٌ، مِائَةٌ وَوَاحِدٌ … أَلْفٌ، أَلْفَانِ، ثَلَاثَةُ آلَافٍ. Feminine: وَاحِدَةٌ، اثْنَتَانِ، ثَلَاثٌ، أَرْبَعٌ … عَشْرٌ، إِحْدَى عَشْرَةَ، اثْنَتَا عَشْرَةَ، ثَلَاثَ عَشْرَةَ … عِشْرُونَ، إِحْدَى وَعِشْرُونَ … تِسْعٌ وَتِسْعُونَ، مِائَةٌ، مِائَةٌ وَوَاحِدَةٌ …"},
  "ar": ["أَحَدَ عَشَرَ", "إِحْدَى عَشْرَةَ", "تِسْعٌ وَتِسْعُونَ"], "notes": ["asma-al-adad-fil-kafiya"], "story": "al-kafiya", "chapter": 10},
 {"n": 30, "q": {"tr": "Sayı isimlerinin temyizleri nasıldır?", "en": "How are the number nouns' tamyīz formed?"},
  "a": {"tr": "ثَلَاثَةٌ'ten عَشَرَةٌ'ye cem' mecrûr (ثَلَاثَةُ رِجَالٍ، ثَلَاثُ نِسَاءٍ); أَحَدَ عَشَرَ'den تِسْعَةٌ وَتِسْعُونَ'a müfred mansûb (أَحَدَ عَشَرَ كَوْكَبًا، إِحْدَى عَشْرَةَ امْرَأَةً); مِائَة، أَلْف, ikisinin tesniyesi ve أَلْف'in cem'i için müfred mecrûr (مِائَةُ رَجُلٍ، أَلْفُ دِرْهَمٍ); وَاحِدٌ ve اثْنَانِ'nin temyizi yoktur, temyize elverişli lafızlarla kullanılırlar (رَجُلٌ، رَجُلَانِ).",
        "en": "From ثَلَاثَةٌ to عَشَرَةٌ a plural in jarr (ثَلَاثَةُ رِجَالٍ، ثَلَاثُ نِسَاءٍ); from أَحَدَ عَشَرَ to تِسْعَةٌ وَتِسْعُونَ a singular in naṣb (أَحَدَ عَشَرَ كَوْكَبًا، إِحْدَى عَشْرَةَ امْرَأَةً); for مِائَة، أَلْف, their duals and the plural of أَلْف, a singular in jarr (مِائَةُ رَجُلٍ، أَلْفُ دِرْهَمٍ); وَاحِدٌ and اثْنَانِ have no tamyīz and go with the counted noun itself (رَجُلٌ، رَجُلَانِ)."},
  "ar": ["ثَلَاثَةُ رِجَالٍ", "أَحَدَ عَشَرَ كَوْكَبًا", "مِائَةُ رَجُلٍ"], "notes": ["asma-al-adad-fil-kafiya", "tamyiz"], "story": "al-kafiya", "chapter": 10},
 {"n": 31, "q": {"tr": "Müteaddidden müfred kaç itibarla söylenir?", "en": "In how many ways is the ordinal formed from the cardinal?"},
  "a": {"tr": "İki itibarla: tasyîr itibarıyla (eksik sayıya katılıp onu bir üst mertebeye çıkarması) الثَّانِي'den الْعَاشِرُ'a cârîdir; hâl itibarıyla (mertebe ile) الْأَوَّلُ، الثَّانِي (الثَّانِيَةُ) … الْعَاشِرُ (الْعَاشِرَةُ)، الْحَادِيَ عَشَرَ (الْحَادِيَةَ عَشْرَةَ) …",
        "en": "In two: as «making up» (joining a lesser number and raising it one rank) it runs from الثَّانِي to الْعَاشِرُ; as a rank it runs الْأَوَّلُ، الثَّانِي (الثَّانِيَةُ) … الْعَاشِرُ (الْعَاشِرَةُ)، الْحَادِيَ عَشَرَ (الْحَادِيَةَ عَشْرَةَ) …"},
  "ar": ["الْحَادِيَ عَشَرَ"], "notes": ["asma-al-adad-fil-kafiya"], "story": "al-kafiya", "chapter": 10},
 {"n": 32, "q": {"tr": "Müzekker ve müennesin tarifi nedir? Te'nîs alâmetleri ve kısımları nelerdir?", "en": "How are masculine and feminine defined, and what are the signs and kinds of the feminine?"},
  "a": {"tr": "Müennes: lafzan ya da takdiren kendisinde te'nîs alâmeti bulunandır — lafzan: امْرَأَةٌ، حُبْلَى، حَمْرَاءُ; takdiren: semâî müennesler, دَارٌ، نَارٌ. Alâmetleri üçtür: üzerinde hâ diye durulan tâ, elif-i maksûre, elif-i memdûde. İki kısım: hakikî — hayvanlardan karşısında bir erkek bulunan (امْرَأَةٌ، نَاقَةٌ); lafzî — karşısında erkek bulunmayan (ظُلْمَةٌ، عَيْنٌ). Müzekker: kendisinde ne lafzan ne takdiren te'nîs alâmeti bulunmayandır.",
        "en": "The feminine: what carries a sign of femininity in wording or by estimation — in wording امْرَأَةٌ، حُبْلَى، حَمْرَاءُ; by estimation the heard feminines دَارٌ، نَارٌ. Three signs: the tāʾ paused on as hāʾ, the shortened alif, the lengthened alif. Two kinds: real — with a male counterpart among living things (امْرَأَةٌ، نَاقَةٌ); in wording — with none (ظُلْمَةٌ، عَيْنٌ). The masculine: what carries no sign of femininity in wording or by estimation."},
  "ar": ["مَا فِيهِ عَلَامَةُ التَّأْنِيثِ لَفْظًا أَوْ تَقْدِيرًا", "مَا بِإِزَائِهِ ذَكَرٌ مِنَ الْحَيَوَانِ", "مَا لَمْ يُوجَدْ فِيهِ عَلَامَةُ التَّأْنِيثِ لَا لَفْظًا وَلَا تَقْدِيرًا"], "notes": ["al-muannath-wal-mudhakkar-fil-kafiya", "al-muannath-wa-alamatuh"], "story": "al-kafiya", "chapter": 11},
 {"n": 33, "q": {"tr": "Tesniyenin tarifi nedir?", "en": "How is the dual defined?"},
  "a": {"tr": "Cinsinden bir benzerinin kendisiyle birlikte bulunduğuna delâlet etsin diye sonuna elif ya da mâkabli meftuh yâ ile mekûr nûn bitişen kelimedir: مُسْلِمَانِ، مُسْلِمَيْنِ.", "en": "A word whose end takes an alif, or a yāʾ after a fatḥa, with a nūn bearing kasra, to show that with it is another of its kind: مُسْلِمَانِ، مُسْلِمَيْنِ."},
  "ar": ["مَا لَحِقَ آخِرَهُ أَلِفٌ أَوْ يَاءٌ مَفْتُوحٌ مَا قَبْلَهَا وَنُونٌ مَكْسُورَةٌ لِيَدُلَّ عَلَى أَنَّ مَعَهُ مِثْلَهُ مِنْ جِنْسِهِ"], "notes": ["al-muthanna-fil-kafiya", "al-muthanna"], "story": "al-kafiya", "chapter": 12},
 {"n": 34, "q": {"tr": "Cem'in tarifi nedir? Kaç kısımdır?", "en": "How is the plural defined, and how many kinds has it?"},
  "a": {"tr": "Bir değişmeyle, müfredinin harfleriyle kastedilen fertlere delâlet eden isimdir. İki kısım: sahih (müzekker ve müennes) ve mükesser.", "en": "A noun that, by some change, signifies the intended units with the letters of its singular. Two kinds: sound (masculine and feminine) and broken."},
  "ar": ["مَا دَلَّ عَلَى آحَادٍ مَقْصُودَةٍ بِحُرُوفِ مُفْرَدِهِ بِتَغَيُّرٍ مَا"], "notes": ["jam", "al-jam-al-salim-fil-kafiya"], "story": "al-kafiya", "chapter": 13},
 {"n": 35, "q": {"tr": "Cem'-i müzekker sâlimin tarifi nedir?", "en": "How is the sound masculine plural defined?"},
  "a": {"tr": "Müfrediyle beraber ondan çoğuna delâlet etsin diye müfredinin sonuna mâkabli mazmûm vâv ya da mâkabli meksûr yâ ile meftuh nûn bitişen cem'dir: مُسْلِمُونَ، مُسْلِمِينَ.", "en": "A plural whose singular takes at its end a wāw after a ḍamma, or a yāʾ after a kasra, with a nūn bearing fatḥa, to show more than one of it: مُسْلِمُونَ، مُسْلِمِينَ."},
  "ar": ["مَا لَحِقَ آخِرَ مُفْرَدِهِ وَاوٌ مَضْمُومٌ مَا قَبْلَهَا أَوْ يَاءٌ مَكْسُورٌ مَا قَبْلَهَا وَنُونٌ مَفْتُوحَةٌ لِيَدُلَّ عَلَى أَنَّ مَعَهُ أَكْثَرَ مِنْهُ"], "notes": ["jam-mudhakkar-salim", "al-jam-al-salim-fil-kafiya"], "story": "al-kafiya", "chapter": 13},
 {"n": 36, "q": {"tr": "Cem'-i müennesin tarifi nedir?", "en": "How is the sound feminine plural defined?"},
  "a": {"tr": "Müfredinin sonuna elif ve tâ bitişen cem'dir: مُسْلِمَاتٌ.", "en": "A plural whose singular takes an alif and a tāʾ at its end: مُسْلِمَاتٌ."},
  "ar": ["مَا لَحِقَ آخِرَهُ أَلِفٌ وَتَاءٌ"], "notes": ["jam-muannath-salim", "al-jam-al-salim-fil-kafiya"], "story": "al-kafiya", "chapter": 13},
 {"n": 37, "q": {"tr": "Cem'-i mükesserin tarifi nedir? Cem'-i kıllet ve cem'-i kesret vezinleri nelerdir?", "en": "How is the broken plural defined, and which patterns are of paucity and of multitude?"},
  "a": {"tr": "Tekilinin yapısı değişen cem'dir. Kıllet vezinleri: أَفْعُلٌ، أَفْعَالٌ، أَفْعِلَةٌ، فِعْلَةٌ ve sahih cem'ler; bunların dışındakiler kesrettir.", "en": "A plural in which the build of its singular changes. Paucity: أَفْعُلٌ، أَفْعَالٌ، أَفْعِلَةٌ، فِعْلَةٌ and the sound plurals; all else is multitude."},
  "ar": ["مَا تَغَيَّرَ بِنَاءُ وَاحِدِهِ"], "notes": ["jam-taksir", "jam-al-taksir-fil-kafiya"], "story": "al-kafiya", "chapter": 14},
 {"n": 38, "q": {"tr": "Masdarın tarifi nedir? Nasıl amel eder?", "en": "How is the masdar defined, and how does it govern?"},
  "a": {"tr": "Fiil üzere cereyan eden hadesin ismidir. Mef'ûl-i mutlak olmadığında mâzîde ve diğerlerinde fiil gibi amel eder; mef'ûl-i mutlak olduğunda amel fiilindir. Hazfedilmiş fiilin yerine gelirse iki vecih câizdir: amelde asıl fiil olduğu için amel fiile, ya da masdar fiilin yerine kâim olduğu için masdara aittir. Lâm-ı ta'rifli masdarın ameli azdır.",
        "en": "The name of the event that runs on the verb's pattern. When it is not an absolute object it governs like its verb in the past and elsewhere; as an absolute object the governing is the verb's. Standing for a dropped verb, two views: the governing belongs to the verb, the root of governing, or to the masdar standing in its place. A masdar with the article governs rarely."},
  "ar": ["اسْمُ الْحَدَثِ الْجَارِي عَلَى الْفِعْلِ"], "notes": ["masdar", "al-masdar-fil-kafiya", "imal-al-masdar"], "story": "al-kafiya", "chapter": 15},
 {"n": 39, "q": {"tr": "İsm-i fâilin tarifi nedir? Nasıl amel eder? Amel şartları nelerdir?", "en": "How is the active participle defined, how does it govern, and on what conditions?"},
  "a": {"tr": "Hudûs mânâsıyla, fiil kendisiyle kâim olan için fiilden türetilen isimdir. Türediği fiil gibi amel eder. Şartları: lâm-ı ta'rifli ise tasgîr edilmemiş ve mevsûf olmamalı; lâm'dan mücerredse bunlarla birlikte mübteda, mevsûf, mevsûl, zi'l-hâl, istifham hemzesi ya da nefiy harfinden birine dayanmalı. Mef'ûlün bihte amel etmesi için ayrıca hâl ya da istikbale delâlet şarttır; mâzî mânâsında ise mef'ûlüne izafeti vâciptir.",
        "en": "A noun derived from a verb for the one in whom the act stands, in the sense of occurrence. It governs as its verb does. Conditions: with the article, it must be neither diminutive nor itself described; without it, also leaning on a mubtadaʾ, a described noun, a relative, an owner of a ḥāl, the question-hamza or a negation. To govern a direct object it must also mean the present or future; in a past sense it must be annexed to its object."},
  "ar": ["مَا اشْتُقَّ مِنْ فِعْلٍ لِمَنْ قَامَ بِهِ بِمَعْنَى الْحُدُوثِ"], "notes": ["ism-fail", "shurut-amal-ism-al-fail", "ism-al-fail-wal-maful-fil-kafiya"], "story": "al-kafiya", "chapter": 16},
 {"n": 40, "q": {"tr": "İsm-i mef'ûlün tarifi nedir? Nasıl amel eder?", "en": "How is the passive participle defined, and how does it govern?"},
  "a": {"tr": "Fiil kendisi üzerine vâki olan için fiilden türetilendir. Amelde hükmü ve şartları ism-i fâilin hükmü gibidir.", "en": "What is derived from a verb for the one on whom the act falls. In governing, its ruling and conditions are the active participle's."},
  "ar": ["مَا اشْتُقَّ مِنْ فِعْلٍ لِمَنْ وَقَعَ عَلَيْهِ"], "notes": ["ism-maful", "ism-al-fail-wal-maful-fil-kafiya"], "story": "al-kafiya", "chapter": 16},
 {"n": 41, "q": {"tr": "Sıfat-ı müşebbehenin tarifi nedir? Nasıl amel eder? Meselelerinin taksimi nasıldır?", "en": "How is the ṣifa mushabbaha defined, how does it govern, and how are its cases divided?"},
  "a": {"tr": "Sübût mânâsıyla, fiil kendisiyle kâim olan için lâzım fiilden türetilendir. Mutlak olarak bütün zamanlarda fiili gibi amel eder. Kendisi lâm'lı ya da lâm'sız; ma'mûlü muzâf, lâm'lı ya da ikisinden mücerred olur — altı sûret: حَسَنٌ وَجْهُهُ / الْحَسَنُ وَجْهُهُ، حَسَنُ الْوَجْهِ / الْحَسَنُ الْوَجْهِ، حَسَنُ وَجْهٍ / الْحَسَنُ وَجْهٍ; her biri merfû, mansûb ve mecrûr olmakla on sekiz vecih. الْحَسَنُ وَجْهُهُ (izafetle) hafiflik olmadığından, الْحَسَنُ وَجْهٍ ma'rife nekreye muzâf olduğundan mümtenidir; حَسَنُ وَجْهِهِ ihtilaflıdır. Kalan on beşten tek zamirli olan ahsen (الْحَسَنُ الْوَجْهِ), iki zamirli olan hasen (الْحَسَنُ وَجْهُهُ), zamirsiz olan kabîhtir (الْحَسَنُ الْوَجْهُ).",
        "en": "What is derived from an intransitive verb for the one in whom the quality stands, in the sense of permanence. It governs like its verb at all times. It comes with or without the article, and its governed word annexed, with the article, or bare of both — six forms: حَسَنٌ وَجْهُهُ / الْحَسَنُ وَجْهُهُ، حَسَنُ الْوَجْهِ / الْحَسَنُ الْوَجْهِ، حَسَنُ وَجْهٍ / الْحَسَنُ وَجْهٍ, each in the three cases — eighteen readings. الْحَسَنُ وَجْهُهُ (by annexation) is barred for lacking lightness, الْحَسَنُ وَجْهٍ for annexing a definite to an indefinite; حَسَنُ وَجْهِهِ is disputed. Of the fifteen left, the one with a single pronoun is best (الْحَسَنُ الْوَجْهِ), with two pronouns good (الْحَسَنُ وَجْهُهُ), with none poor (الْحَسَنُ الْوَجْهُ)."},
  "ar": ["مَا اشْتُقَّ مِنْ فِعْلٍ لَازِمٍ لِمَنْ قَامَ بِهِ بِمَعْنَى الثُّبُوتِ", "حَسَنٌ وَجْهُهُ", "حَسَنُ الْوَجْهِ"], "notes": ["sifa-mushabbaha", "al-sifa-al-mushabbaha-fil-kafiya", "masail-al-sifa-al-mushabbaha-fil-kafiya"], "story": "al-kafiya", "chapter": 17},
 {"n": 42, "q": {"tr": "İsm-i tafdîlin tarifi ve amel şartları nelerdir?", "en": "How is the elative defined, and on what conditions does it govern?"},
  "a": {"tr": "Başkası üzerine bir ziyadeyle mevsûf için fiilden türetilendir. Amel şartları: lafzan bir şeye sıfat olacak (o şey mâ cerâ aleyh'tir); mâ cerâ aleyh'in müteallakına mânen sıfat olacak; müteallak, kendi nefsine (mâ cerâ aleyh'e) taalluk itibarıyla mufaddal, başkasına taalluk itibarıyla mufaddalün aleyh olacak; kelâm menfî olacak (nefiyle üçüncü ve dördüncü maddelerdeki hüküm tersine döner).",
        "en": "What is derived from a verb for one described as exceeding another. Conditions for governing: it is in wording an adjective of something (that on which it runs); in meaning an adjective of something tied to that thing; the tied thing is the excelling one with respect to that on which the elative runs, and the excelled one with respect to another; and the sentence is negated (the negation reversing the third and fourth)."},
  "ar": ["مَا اشْتُقَّ مِنْ فِعْلٍ لِمَوْصُوفٍ بِزِيَادَةٍ عَلَى غَيْرِهِ"], "notes": ["ism-tafdil", "ism-al-tafdil-fil-kafiya", "amal-ism-al-tafdil-wal-masdar"], "story": "al-kafiya", "chapter": 19},
]
